121	  int ret;
122	  size_t bodylen;
123	  cJSON *root = NULL;
124	  cJSON *ws = NULL;
125	  cJSON *url = NULL;
126	  cJSON *token = NULL;
127	
128	  if (mac == NULL || ota_out == NULL)
129	    {
