3006	void xiaozhi_voice_delete(void)
3007	{
3008	  printf("[xiaozhi] xiaozhi_voice_delete: starting cleanup\n");
3009	
3010	  /* Signal all threads to stop. */
3011	  g_app.app_running = false;
3012	  g_app.ws_connected = false;
3013	  g_app.capturing = false;
3014	  g_app.capture_stop = true;
3015	
3016	  /* First, unblock recv_thread from any pending mbedtls_ssl_read by closing
3017	   * the underlying socket. This causes mbedtls_ssl_read to return immediately
3018	   * with a transport error, so recv_thread can exit cleanly. Without this,
3019	   * recv_thread would be blocked in TLS read and accessing freed memory when
3020	   * we later call xiaozhi_ws_close. */
3021	  if (g_app.ws.fd >= 0)
3022	    {
3023	      printf("[xiaozhi] closing socket fd %d to unblock recv_thread\n",
3024	             g_app.ws.fd);
3025	      close(g_app.ws.fd);
3026	      g_app.ws.fd = -1;
3027	    }
3028	
3029	  /* Now wait for recv_thread to exit. It should exit quickly since the
3030	   * socket is closed and ws_connected is false. */
3031	  if (g_app.recv_tid_valid)
3032	    {
3033	      printf("[xiaozhi] joining recv_thread\n");
3034	      pthread_join(g_app.recv_tid, NULL);
3035	      g_app.recv_tid_valid = false;
3036	      printf("[xiaozhi] recv_thread joined\n");
3037	    }
3038	
3039	  /* If a capture thread is mid-flight (Speak was held on exit), wait for its
3040	   * start_capture to finish, then stop the recorder so its blocking read
3041	   * unblocks, then join — so it doesn't touch freed audio/LVGL state. */
3042	  if (g_app.capture_tid_valid)
3043	    {
3044	      int spin = 0;
3045	      while (!g_app.capture_started && spin < 3000)
3046	        {
3047	          usleep(10 * 1000);
3048	          spin += 10;
3049	        }
3050	      if (g_app.audio != NULL)
3051	        {
3052	          xiaozhi_audio_stop_capture(g_app.audio);
3053	        }
3054	      pthread_join(g_app.capture_tid, NULL);
3055	      g_app.capture_tid_valid = false;
3056	      g_app.capture_started = false;
3057	    }
3058	  else if (g_app.audio != NULL)
3059	    {
3060	      xiaozhi_audio_stop_capture(g_app.audio);
3061	    }
3062	
3063	  /* Wait for connect_thread to finish. It will exit its main loop when
3064	   * app_running becomes false. We must wait for it before freeing g_app
3065	   * resources since it may still be accessing them. */
3066	  if (g_app.connect_tid_valid)
3067	    {
3068	      printf("[xiaozhi] joining connect_thread\n");
3069	
3070	      /* Close the WebSocket socket to interrupt any blocking TLS/WS I/O.
3071	       * This causes mbedtls_ssl_handshake / mbedtls_ssl_read to fail
3072	       * immediately, so connect_thread can check app_running and exit. */
3073	      if (g_app.ws.fd >= 0)
3074	        {
3075	          printf("[xiaozhi] closing ws fd %d to interrupt blocking I/O\n",
3076	                 g_app.ws.fd);
3077	          close(g_app.ws.fd);
3078	          g_app.ws.fd = -1;
3079	        }
3080	
3081	      /* connect_thread may be sleeping in reconnect delay (sleep(3) or sleep(5)),
3082	       * or blocked in wait_connected loop. Setting app_running=false will cause
3083	       * it to exit the loop at the next iteration. Give it time to finish. */
3084	      int spin = 0;
3085	      while (g_app.connect_tid_valid && spin < 2000)
3086	        {
3087	          usleep(10 * 1000);
3088	          spin += 10;
3089	        }
3090	      /* Note: We don't pthread_join connect_thread here because it might be
3091	       * blocked in sleep(3) or sleep(5) during reconnect. Instead, we rely
3092	       * on the usleep above and the fact that connect_thread checks
3093	       * app_running in its loop. The final memset will zero out g_app
3094	       * after connect_thread has exited. */
3095	      g_app.connect_tid_valid = false;
3096	      printf("[xiaozhi] connect_thread cleanup done\n");
3097	    }
3098	
3099	  /* Final cleanup: close websocket and deinit audio.
3100	   * This must happen AFTER all threads have exited to avoid use-after-free. */
3101	  printf("[xiaozhi] final cleanup: ws_close + audio_deinit\n");
3102	  if (g_app.tts_playing)
3103	    {
3104	      xiaozhi_audio_stop_playback(g_app.audio);
3105	    }
3106	  xiaozhi_ws_close(&g_app.ws);
3107	  if (g_app.audio != NULL)
3108	    {
3109	      xiaozhi_audio_deinit(g_app.audio);
3110	      g_app.audio = NULL;
3111	    }
3112	
3113	  /* ---- LVGL cleanup (DEFERRED) ----
3114	   *
3115	   * CRITICAL: Do NOT call lv_obj_del() anywhere. It corrupts the TLSF
3116	   * heap on BES1700, causing必现 MMFAR=0x15c crash on next render cycle.
3117	   * The deferred callback hides the container, deletes custom timers, and
3118	   * NULLs out all pointers — accepting the small memory leak.
3119	   */
3120	
3121	  /* 1. Hide the container — LVGL will skip drawing it. */
3122	  if (xiaozhi_container != NULL)
3123	    {
3124	      lv_obj_add_flag(xiaozhi_container, LV_OBJ_FLAG_HIDDEN);
3125	    }
3126	
3127	  /* 2. Schedule deferred cleanup for the next timer tick. */
3128	  if (s_deferred_delete_timer == NULL)
3129	    {
3130	      s_deferred_delete_timer = lv_timer_create(deferred_lvgl_delete_cb,
3131	                                                1, NULL);
3132	      lv_timer_set_repeat_count(s_deferred_delete_timer, 1);
3133	    }
3134	
3135	  printf("[xiaozhi] cleanup scheduled (deferred LVGL delete)\n");
3136	}
