2952	
2953	  /* ---- Timer cleanup (before container deletion) ---- */
2954	  if (s_timer != NULL) { lv_timer_del(s_timer); s_timer = NULL; }
2955	  if (s_think_timer != NULL) { lv_timer_del(s_think_timer); s_think_timer = NULL; }
2956	  if (s_dot_pulse_timer != NULL) { lv_timer_del(s_dot_pulse_timer); s_dot_pulse_timer = NULL; }
2957	  if (s_recog_anim_timer != NULL) { lv_timer_del(s_recog_anim_timer); s_recog_anim_timer = NULL; }
