2960	  if (s_orbit_timer != NULL) { lv_timer_del(s_orbit_timer); s_orbit_timer = NULL; }
2961	  if (ui_refresh_timer != NULL) { lv_timer_delete(ui_refresh_timer); ui_refresh_timer = NULL; }
2962	
2963	  /* ---- Do NOT call lv_obj_del — it corrupts the TLSF heap on this
2964	   * embedded system and causes a必现 Memory Management Fault crash
2965	   * (MMFAR=0x15c) on the next render cycle. The container is already
2966	   * hidden with LV_OBJ_FLAG_HIDDEN, so LVGL skips it during rendering.
2967	   * We just NULL out the pointer — the small memory leak is acceptable
2968	   * on an embedded watch that restarts on the next app launch. */
