258	/* Read exactly n bytes over TLS into buf. Returns 0 on success, -errno. */
259	static int ws_tls_read_all(struct xiaozhi_ws_s *ws, uint8_t *buf, size_t n)
260	{
261	  size_t got = 0;
262	  while (got < n)
263	    {
264	      int ret = mbedtls_ssl_read(&ws->ssl, buf + got, n - got);
265	      if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
266	          ret == MBEDTLS_ERR_SSL_WANT_WRITE)
267	        {
268	          continue;
269	        }
270	
271	      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
272	        {
273	          printf("[xiaozhi] tls peer closed during read\n");
274	          return -ECONNRESET;
275	        }
276	
277	      if (ret < 0)
278	        {
279	          printf("[xiaozhi] tls read error: -0x%x\n", -ret);
280	          return -EIO;
281	        }
282	
283	      got += ret;
284	    }
285	
286	  return 0;
287	}
