/* Signal all threads to stop. */
g_app.app_running = false;
g_app.ws_connected = false;
g_app.capturing = false;
g_app.capture_stop = true;

/* First, unblock recv_thread from any pending mbedtls_ssl_read by closing
 * the underlying socket. This causes mbedtls_ssl_read to return immediately
 * with a transport error, so recv_thread can exit cleanly. Without this,
 * recv_thread would be blocked in TLS read and accessing freed memory when
 * we later call xiaozhi_ws_close. */
if (g_app.ws.fd >= 0)
  {
    printf("[xiaozhi] closing socket fd %d to unblock recv_thread\n",
           g_app.ws.fd);
    close(g_app.ws.fd);
    g_app.ws.fd = -1;
  }

/* Now wait for connect_thread to exit first. It may be in a reconnect
 * loop with sleep calls, so we need to wait for it to finish.
 * NOTE: connect_thread checks app_running in its sleep loops and will
 * exit within a few seconds (max 3s from any sleep point). */
if (g_app.connect_tid_valid)
  {
    printf("[xiaozhi] waiting for connect_thread to exit\n");
    /* Wait up to 10 seconds for connect_thread to exit. It should exit
     * quickly since app_running is now false. */
    int wait_ms = 0;
    while (g_app.connect_tid_valid && wait_ms < 10000)
      {
        usleep(100 * 1000);  /* 100ms */
        wait_ms += 100;
      }
    if (g_app.connect_tid_valid)
      {
        printf("[xiaozhi] WARNING: connect_thread did not exit in time\n");
      }
    else
      {
        printf("[xiaozhi] connect_thread exited\n");
      }
  }

/* Now wait for recv_thread to exit. It should exit quickly since the
 * socket is closed and ws_connected is false. */
if (g_app.recv_tid_valid)
  {
    printf("[xiaozhi] joining recv_thread\n");
    pthread_join(g_app.recv_tid, NULL);
    g_app.recv_tid_valid = false;
    printf("[xiaozhi] recv_thread joined\n");
  }

/* If a capture thread is mid-flight (Speak was held on exit), wait for its
 * start_capture to finish, then stop the recorder so its blocking read
 * unblocks, then join — so it doesn't touch freed audio/LVGL state. */
if (g_app.capture_tid_valid)
  {
    int spin = 0;
    while (!g_app.capture_started && spin < 3000)
      {
        usleep(10 * 1000);
        spin += 10;
      }
    if (g_app.audio != NULL)
      {
        xiaozhi_audio_stop_capture(g_app.audio);
      }
    pthread_join(g_app.capture_tid, NULL);
    g_app.capture_tid_valid = false;
    g_app.capture_started = false;
  }
else if (g_app.audio != NULL)
  {
    xiaozhi_audio_stop_capture(g_app.audio);
  }

/* Final cleanup: close websocket and deinit audio.
 * This must happen AFTER all threads have exited to avoid use-after-free. */
printf("[xiaozhi] final cleanup: ws_close + audio_deinit\n");
if (g_app.tts_playing)
  {
    xiaozhi_audio_stop_playback(g_app.audio);
  }
xiaozhi_ws_close(&g_app.ws);
if (g_app.audio != NULL)
  {
    xiaozhi_audio_deinit(g_app.audio);
    g_app.audio = NULL;
  }

