    }

  /* 2. NULL out all LVGL pointers immediately.
   * The container is hidden, so LVGL won't render it.
   * The pointers are NULL, so no code will access freed objects. */
  xiaozhi_container = NULL;
  s_bubble_alarm = NULL;
