/****************************************************************************
 * Safe LVGL object cleanup — hides the object instead of calling lv_obj_del.
 *
 * CRITICAL: Do NOT call lv_obj_del() anywhere in this file. It corrupts the
 * TLSF heap on BES1700, causing必现 MMFAR=0x15c crash on next render cycle.
 * Instead, hide the object with LV_OBJ_FLAG_HIDDEN and set the pointer to NULL.
 * The small memory leak is acceptable on an embedded watch.
 ****************************************************************************/
static inline void safe_obj_hide_and_null(lv_obj_t **obj_ptr)
{
    if (*obj_ptr != NULL)
    {
        lv_obj_add_flag(*obj_ptr, LV_OBJ_FLAG_HIDDEN);
        *obj_ptr = NULL;
    }
}

