static int ws_tls_read_all(struct xiaozhi_ws_s *ws, uint8_t *buf, size_t n)
{
  size_t got = 0;
  printf("[xiaozhi] ws_tls_read_all: n=%zu, ws->connected=%d, ws->fd=%d\n",
         n, ws->connected, ws->fd);
  while (got < n)
    {
      printf("[xiaozhi] ws_tls_read_all: calling mbedtls_ssl_read, got=%zu, need=%zu\n",
             got, n - got);
      int ret = mbedtls_ssl_read(&ws->ssl, buf + got, n - got);
      printf("[xiaozhi] ws_tls_read_all: mbedtls_ssl_read returned %d\n", ret);
      if (ret == MBEDTLS_ERR_SSL_WANT_READ ||
          ret == MBEDTLS_ERR_SSL_WANT_WRITE)
        {
          printf("[xiaozhi] ws_tls_read_all: WANT_READ/WANT_WRITE, continuing\n");
          continue;
        }

      if (ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY || ret == 0)
        {
          printf("[xiaozhi] tls peer closed during read\n");
          return -ECONNRESET;
        }

      if (ret < 0)
        {
          printf("[xiaozhi] tls read error: -0x%x\n", -ret);
          return -EIO;
        }

      got += ret;
    }

  printf("[xiaozhi] ws_tls_read_all: complete, got=%zu\n", got);
  return 0;
}

